-- Minimal fixtures matching the inspected production column types. Isolated PGlite only.
create table public.profiles(id uuid primary key,display_name text default 'جار',city text default 'الرياض',district text default 'العليا',role text default 'user',is_banned boolean not null default false,is_verified boolean not null default false,notification_preferences jsonb not null default '{}',permissions jsonb default '{}');
create table public.banned_words(word text,enabled boolean default true);
create function app_private.hayna_user_has_permission(p_user uuid,p_permission text) returns boolean language sql stable security definer set search_path=pg_catalog as $$select coalesce((select not is_banned and permissions->>p_permission='true' from public.profiles where id=p_user),false)$$;
create function public.hayna_has_permission(p_permission text) returns boolean language sql stable security definer set search_path=pg_catalog as $$select app_private.hayna_user_has_permission(auth.uid(),p_permission)$$;
revoke all on function app_private.hayna_user_has_permission(uuid,text) from public,anon,authenticated;
grant execute on function public.hayna_has_permission(text) to anon,authenticated;
create table public.requests(id uuid primary key default gen_random_uuid(),requester_id uuid not null references public.profiles(id),title text not null,description text not null,city text not null,district text,budget numeric,request_type text default 'help',status text default 'open');
alter table public.requests enable row level security;
create policy requests_read on public.requests for select to authenticated using(true);
create policy requests_insert on public.requests for insert to authenticated with check(requester_id=auth.uid() and exists(select 1 from public.profiles where id=auth.uid() and not is_banned));
create table public.request_tags(request_id uuid not null references public.requests(id) on delete cascade,tag text not null check(length(trim(tag)) between 1 and 40),primary key(request_id,tag));
alter table public.request_tags enable row level security;
create policy "request tags requester insert" on public.request_tags for insert to authenticated with check(exists(select 1 from public.requests where id=request_id and requester_id=auth.uid()));
create policy "request tags requester delete" on public.request_tags for delete to authenticated using(exists(select 1 from public.requests where id=request_id and requester_id=auth.uid()));
create table public.borrow_items(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id),title text not null,description text,category text not null default 'tools',image_url text,city text not null default 'الرياض',district text not null default 'العليا',status text not null default 'available',max_days integer not null default 3,deposit_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.borrow_requests(id uuid primary key default gen_random_uuid(),item_id uuid not null references public.borrow_items(id) on delete cascade,borrower_id uuid not null references public.profiles(id),status text not null default 'pending',start_date date not null default current_date,duration_days integer not null default 1,note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.borrow_items enable row level security;alter table public.borrow_requests enable row level security;
create table public.conversations(id uuid primary key default gen_random_uuid(),created_by uuid,created_at timestamptz default now());
create table public.conversation_members(conversation_id uuid references public.conversations(id),user_id uuid references public.profiles(id),primary key(conversation_id,user_id));
create function public.hayna_can_dm(p_user uuid,p_target uuid) returns boolean language sql stable as $$select p_user<>p_target and p_user is not null and p_target is not null$$;
create function public.hayna_get_or_create_direct_conversation(p_target uuid) returns uuid language plpgsql security definer as $$declare c uuid;begin insert into public.conversations(created_by) values(auth.uid()) returning id into c;insert into public.conversation_members values(c,auth.uid()),(c,p_target);return c;end$$;
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id),target_type text not null,target_id uuid not null,reason text not null,status text not null default 'pending',created_at timestamptz default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),type text not null,title text not null,body text,data jsonb not null default '{}',read_at timestamptz,created_at timestamptz default now(),target_type text,target_id uuid);
create table public.admin_activity_logs(id uuid primary key default gen_random_uuid(),actor_id uuid not null references public.profiles(id),action text not null,target_type text,target_id uuid,metadata jsonb default '{}',created_at timestamptz default now());
create table public.urgent_alerts(id uuid primary key default gen_random_uuid(),creator_id uuid not null references public.profiles(id),title text not null,description text not null,alert_type text not null default 'general',city text not null default 'الرياض',district text not null default 'العليا',status text not null default 'active',location_lat float8,location_lng float8,created_at timestamptz not null default now(),resolved_at timestamptz,edit_count integer not null default 0);
alter table public.urgent_alerts enable row level security;
create table public.scheduled_broadcasts(id uuid primary key default gen_random_uuid(),title text not null,body text not null,broadcast_type text not null default 'official',target jsonb not null default '{"scope":"all","segment":"all"}',scheduled_at timestamptz not null,status text not null default 'pending',sent_at timestamptz,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
alter table public.scheduled_broadcasts enable row level security;
create function app_private.run_backend_job(p_task text) returns jsonb language sql security definer as $$select jsonb_build_object('original_task',p_task)$$;
grant select on public.profiles,public.requests to anon,authenticated;
grant insert on public.requests to authenticated;
grant all on public.request_tags,public.borrow_items,public.borrow_requests,public.scheduled_broadcasts,public.urgent_alerts to anon,authenticated;
